/**
 * Host-generated goldens for the Worker `cmp` vectors.
 *
 * `golden.mjs` compares the Worker command surface with committed bytes; a
 * hand-written expectation is only as good as the author's memory of the
 * program. `cmp` is a POSIX program whose stdout/stderr shapes and 0/1/2
 * statuses scripts (and the G2-D04 idempotency check) parse, so its vectors are
 * generated by running the **host** `/usr/bin/cmp` on the same fixtures:
 *
 * ```sh
 * node tools/shell-corpus/cmp-golden.mjs --write          # regenerate in place
 * node tools/shell-corpus/cmp-golden.mjs --check          # drift gate
 * node tools/shell-corpus/cmp-golden.mjs                  # print the vectors
 * ```
 *
 * The generated records use the compact vector shape (`cmd`, `fixture`,
 * `expect`) understood by `golden.mjs`/`contract.mjs`, and `--write` replaces
 * only the records whose name starts with {@link CMP_VECTOR_PREFIX}; every
 * other committed vector is left byte for byte alone. The committed goldens
 * are the BSD host shape (macOS); on a GNU `cmp` host `--check` reports the
 * difference instead of silently accepting a second shape, and
 * `cmp-golden.test.mjs` skips the host comparison when the local program is not
 * the shape the file was generated from.
 * @module tools/shell-corpus/cmp-golden
 */

import { accessSync, constants as fsConstants, mkdirSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs'
import { spawnSync } from 'node:child_process'
import { tmpdir } from 'node:os'
import { dirname, isAbsolute, join, resolve } from 'node:path'
import { fileURLToPath, pathToFileURL } from 'node:url'

/** Committed vector file. */
export const DEFAULT_GOLDEN = fileURLToPath(new URL('./golden/worker-shell.jsonl', import.meta.url))

/** The host program the goldens are generated from. */
export const DEFAULT_CMP = '/usr/bin/cmp'

/** Prefix of every vector this tool owns. */
export const CMP_VECTOR_PREFIX = 'cmp/'

/** Fixtures reused by several vectors. */
const IDENTICAL = Object.freeze({ 'notes/a.md': 'alpha\nbeta\n', 'notes/b.md': 'alpha\nbeta\n' })
const DIFFERENT = Object.freeze({ 'notes/a.md': 'alpha\nbeta\n', 'notes/b.md': 'alpha\nBETA\n' })
const SHORT_LONG = Object.freeze({ 'notes/a.md': 'alpha\n', 'notes/b.md': 'alpha\nbeta\n' })
const TWO_DIFFERENCES = Object.freeze({ 'notes/a.md': 'alpha\nbeta\n', 'notes/b.md': 'alpHa\nbeTa\n' })

/**
 * The committed `cmp` vectors, as the shell command plus the argv the host
 * generator runs.
 *
 * `argv` never reaches the golden file: it names the host program's arguments
 * so generation does not have to re-parse a shell string. `cmd` is the same
 * invocation as the Worker shell sees it.
 */
export const CMP_VECTORS = Object.freeze([
  {
    name: 'cmp/default-identical',
    category: 'files',
    cmd: 'cmp notes/a.md notes/b.md',
    argv: ['notes/a.md', 'notes/b.md'],
    fixture: IDENTICAL,
  },
  {
    name: 'cmp/default-first-difference',
    category: 'files',
    cmd: 'cmp notes/a.md notes/b.md',
    argv: ['notes/a.md', 'notes/b.md'],
    fixture: DIFFERENT,
  },
  {
    name: 'cmp/default-eof-on-shorter',
    category: 'files',
    cmd: 'cmp notes/a.md notes/b.md',
    argv: ['notes/a.md', 'notes/b.md'],
    fixture: SHORT_LONG,
  },
  {
    name: 'cmp/silent-identical',
    category: 'files',
    cmd: 'cmp -s notes/a.md notes/b.md',
    argv: ['-s', 'notes/a.md', 'notes/b.md'],
    fixture: IDENTICAL,
  },
  {
    name: 'cmp/silent-differing',
    category: 'files',
    cmd: 'cmp -s notes/a.md notes/b.md',
    argv: ['-s', 'notes/a.md', 'notes/b.md'],
    fixture: DIFFERENT,
  },
  {
    name: 'cmp/silent-eof-on-shorter',
    category: 'files',
    cmd: 'cmp -s notes/a.md notes/b.md',
    argv: ['-s', 'notes/a.md', 'notes/b.md'],
    fixture: SHORT_LONG,
  },
  {
    name: 'cmp/silent-missing-file',
    category: 'files',
    cmd: 'cmp -s notes/missing.md notes/a.md',
    argv: ['-s', 'notes/missing.md', 'notes/a.md'],
    fixture: IDENTICAL,
  },
  {
    name: 'cmp/long-identical',
    category: 'files',
    cmd: 'cmp -l notes/a.md notes/b.md',
    argv: ['-l', 'notes/a.md', 'notes/b.md'],
    fixture: IDENTICAL,
  },
  {
    name: 'cmp/long-lists-bytes',
    category: 'files',
    cmd: 'cmp -l notes/a.md notes/b.md',
    argv: ['-l', 'notes/a.md', 'notes/b.md'],
    fixture: TWO_DIFFERENCES,
  },
  {
    name: 'cmp/long-eof-on-shorter',
    category: 'files',
    cmd: 'cmp -l notes/a.md notes/b.md',
    argv: ['-l', 'notes/a.md', 'notes/b.md'],
    fixture: SHORT_LONG,
  },
  {
    name: 'cmp/missing-operands',
    category: 'files',
    cmd: 'cmp',
    argv: [],
    fixture: Object.freeze({}),
  },
  {
    name: 'cmp/missing-second-operand',
    category: 'files',
    cmd: 'cmp notes/a.md',
    argv: ['notes/a.md'],
    fixture: IDENTICAL,
  },
  {
    name: 'cmp/missing-file',
    category: 'files',
    cmd: 'cmp notes/missing.md notes/a.md',
    argv: ['notes/missing.md', 'notes/a.md'],
    fixture: IDENTICAL,
  },
])

/** Decode one host stream, refusing bytes the vector JSON could not carry. */
function decodeStream(buffer, name, stream) {
  const text = buffer.toString('utf8')
  if (!Buffer.from(text, 'utf8').equals(buffer)) {
    throw new Error(`cmp goldens: ${name} produced non-UTF-8 ${stream}; vector expectations are text`)
  }
  return text
}

/**
 * Run the host `cmp` on every vector fixture.
 *
 * Each vector gets a fresh temporary directory seeded with its fixture, exactly
 * like `createGoldenShell` seeds the Worker VFS, and `cmp` runs there with the
 * relative operands the vector names. The returned records are the committed
 * compact shape (no `argv`).
 *
 * @param {{cmpPath?: string}} [options] - host program override.
 * @returns {object[]} generated vectors in {@link CMP_VECTORS} order.
 */
export function generateCmpGoldens(options = {}) {
  const cmpPath = options.cmpPath ?? DEFAULT_CMP
  try {
    accessSync(cmpPath, fsConstants.X_OK)
  } catch (error) {
    throw new Error(`cmp goldens: ${cmpPath} is not an executable program (${error instanceof Error ? error.message : String(error)})`)
  }
  const vectors = []
  for (const vector of CMP_VECTORS) {
    const root = mkdtempSync(join(tmpdir(), 'pdsh-cmp-golden-'))
    try {
      for (const [relative, content] of Object.entries(vector.fixture)) {
        mkdirSync(dirname(join(root, relative)), { recursive: true })
        writeFileSync(join(root, relative), content, 'utf8')
      }
      const run = spawnSync(cmpPath, vector.argv, { cwd: root, encoding: null, timeout: 30_000 })
      if (run.error !== undefined) {
        throw new Error(`cmp goldens: ${vector.name}: host cmp failed to start (${run.error.message})`)
      }
      if (run.status === null) {
        throw new Error(`cmp goldens: ${vector.name}: host cmp ended on signal ${String(run.signal)}`)
      }
      vectors.push({
        name: vector.name,
        category: vector.category,
        cmd: vector.cmd,
        fixture: vector.fixture,
        expect: {
          stdout: decodeStream(run.stdout, vector.name, 'stdout'),
          stderr: decodeStream(run.stderr, vector.name, 'stderr'),
          exit: run.status,
        },
      })
    } finally {
      rmSync(root, { recursive: true, force: true })
    }
  }
  return vectors
}

/**
 * Serialise generated vectors as the golden file's JSONL lines.
 * @param {object[]} vectors - output of {@link generateCmpGoldens}.
 * @returns {string[]} one JSON object per line, no trailing newline.
 */
export function renderCmpVectors(vectors) {
  return vectors.map(vector => JSON.stringify(vector))
}

/**
 * Replace the `cmp/` records of a golden document at the position of the
 * existing block, preserving every other line byte for byte.
 *
 * Other generators append their vectors to the same file after `cmp` was
 * written, so moving the `cmp/` records to the end would reorder the file and
 * make `--write`/`--check` depend on which generator ran last. Replacing in
 * place keeps every non-`cmp` vector's bytes and order stable, and applying the
 * replacement twice is the same as applying it once even when later lines were
 * appended.
 * @param {string} text - current golden file contents.
 * @param {object[]} vectors - output of {@link generateCmpGoldens}.
 * @returns {string} the next file contents.
 */
export function replaceCmpVectors(text, vectors) {
  const lines = text === '' ? [] : text.replace(/\n$/u, '').split('\n')
  const generated = renderCmpVectors(vectors)
  const next = []
  let inserted = false
  for (const line of lines) {
    let isCmp = false
    try {
      const record = JSON.parse(line)
      isCmp = typeof record?.name === 'string' && record.name.startsWith(CMP_VECTOR_PREFIX)
    } catch {
      // Leave a malformed line for `parseGolden` to report with its line
      // number instead of silently dropping it here.
    }
    if (!isCmp) {
      next.push(line)
      continue
    }
    if (!inserted) {
      next.push(...generated)
      inserted = true
    }
  }
  if (!inserted) next.push(...generated)
  return next.join('\n') + '\n'
}

/**
 * Read the committed `cmp/` records out of a golden document.
 * @param {string} text - golden file contents.
 * @returns {object[]} the committed cmp vectors, in file order.
 */
export function cmpVectorsFromText(text) {
  const vectors = []
  for (const line of text.split(/\r?\n/u)) {
    if (line.trim() === '') continue
    let record
    try {
      record = JSON.parse(line)
    } catch {
      continue
    }
    if (typeof record?.name === 'string' && record.name.startsWith(CMP_VECTOR_PREFIX)) vectors.push(record)
  }
  return vectors
}

/** Print one concise line for `--check` drift. */
function describeDrift(expected, actual) {
  const expectedLines = expected.split('\n')
  const actualLines = actual.split('\n')
  for (let index = 0; index < Math.max(expectedLines.length, actualLines.length); index += 1) {
    if (expectedLines[index] === actualLines[index]) continue
    return `line ${String(index + 1)}: committed ${JSON.stringify(actualLines[index])}, host ${JSON.stringify(expectedLines[index])}`
  }
  return 'the file differs'
}

/**
 * CLI entry point.
 * @param {string[]} argv - arguments after the script name.
 * @returns {Promise<number>} process exit status.
 */
export async function main(argv) {
  let action = 'print'
  let goldenPath = DEFAULT_GOLDEN
  let cmpPath = DEFAULT_CMP
  let quiet = false
  for (let index = 0; index < argv.length; index += 1) {
    const argument = argv[index]
    if (argument === '--help' || argument === '-h') {
      process.stdout.write('usage: node tools/shell-corpus/cmp-golden.mjs [--print|--write|--check] [--golden FILE] [--cmp PATH] [--quiet]\n')
      return 0
    }
    if (argument === '--print' || argument === '--write' || argument === '--check') {
      action = argument.slice(2)
      continue
    }
    if (argument === '--quiet') {
      quiet = true
      continue
    }
    if (argument === '--golden' || argument === '--cmp') {
      const value = argv[index + 1]
      if (value === undefined) {
        process.stderr.write(`cmp-golden: ${argument} needs a value\n`)
        return 2
      }
      if (argument === '--golden') goldenPath = value
      else cmpPath = value
      index += 1
      continue
    }
    process.stderr.write(`cmp-golden: unknown argument '${argument}'\n`)
    return 2
  }
  let generated
  try {
    generated = generateCmpGoldens({ cmpPath })
  } catch (error) {
    process.stderr.write(`${error instanceof Error ? error.message : String(error)}\n`)
    return 2
  }
  if (action === 'print') {
    process.stdout.write(`${renderCmpVectors(generated).join('\n')}\n`)
    return 0
  }
  const file = isAbsolute(goldenPath) ? goldenPath : resolve(goldenPath)
  let current
  try {
    current = readFileSync(file, 'utf8')
  } catch (error) {
    process.stderr.write(`cmp-golden: cannot read ${file}: ${error instanceof Error ? error.message : String(error)}\n`)
    return 2
  }
  const expected = replaceCmpVectors(current, generated)
  if (action === 'write') {
    if (expected !== current) writeFileSync(file, expected, 'utf8')
    if (!quiet) process.stdout.write(`cmp-golden: wrote ${String(generated.length)} cmp vectors to ${file}\n`)
    return 0
  }
  if (expected === current) {
    if (!quiet) process.stdout.write(`cmp-golden: ${String(generated.length)} cmp vectors match the host program\n`)
    return 0
  }
  process.stderr.write(`cmp-golden: committed vectors differ from the host program\n`)
  process.stderr.write(`cmp-golden: ${describeDrift(expected, current)}\n`)
  return 1
}

const invokedDirectly = process.argv[1] !== undefined
  && import.meta.url === pathToFileURL(resolve(process.argv[1])).href

if (invokedDirectly) {
  main(process.argv.slice(2)).then((status) => {
    process.exitCode = status
  }).catch((error) => {
    process.stderr.write(`cmp-golden: ${error instanceof Error ? error.stack ?? error.message : String(error)}\n`)
    process.exitCode = 2
  })
}
